/*
 * prog24_query_string_parser
 *
 * The original binary reads a line from standard input, treats it as a
 * URL‑query string (e.g.  "name=John+Doe&age=27") and prints each
 * key/value pair on its own line after URL‑decoding the components.
 *
 * Behaviour reproduced:
 *   • If no line can be read, prints the literal string "NO_INPUT".
 *   • Handles '&' as a separator between pairs and '=' as the key/value
 *     delimiter.
 *   • Percent‑encoding (%XX) is decoded, and '+' is translated to a space.
 *   • Trailing CR/LF characters are ignored.
 *   • Empty keys or values are allowed – they are printed as empty strings.
 *
 * The implementation below follows the logic observed in the decompiled
 * binary but is written in clean, idiomatic C.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define LINE_MAX   0x800          /* 2048 bytes – matches the original buffer */
#define KEY_MAX    0x100          /* 256 bytes – enough for typical keys   */
#define VAL_MAX    0x100          /* 256 bytes – enough for typical values */

/* ----------------------------------------------------------------------
 * URL‑decode a fragment.
 *
 *  src   – pointer to the fragment to decode
 *  srclen– length of the fragment (in bytes)
 *  dst   – destination buffer (must be large enough)
 *
 * The function writes a NUL‑terminated string to *dst.
 * ---------------------------------------------------------------------- */
static void url_decode(const char *src, size_t srclen, char *dst)
{
    size_t i = 0, j = 0;

    while (i < srclen) {
        char c = src[i];

        if (c == '+') {                     /* '+' → space */
            dst[j++] = ' ';
            ++i;
        } else if (c == '%' && i + 2 < srclen &&
                   isxdigit((unsigned char)src[i+1]) &&
                   isxdigit((unsigned char)src[i+2])) {
            /* %XX → byte value */
            char hi = src[i+1];
            char lo = src[i+2];
            int hi_val = (hi >= '0' && hi <= '9') ? hi - '0' :
                         (hi >= 'a' && hi <= 'f') ? hi - 'a' + 10 :
                         hi - 'A' + 10;
            int lo_val = (lo >= '0' && lo <= '9') ? lo - '0' :
                         (lo >= 'a' && lo <= 'f') ? lo - 'a' + 10 :
                         lo - 'A' + 10;
            dst[j++] = (char)((hi_val << 4) | lo_val);
            i += 3;
        } else {
            dst[j++] = c;
            ++i;
        }
    }
    dst[j] = '\0';
}

/* ----------------------------------------------------------------------
 * Main program – reads one line, parses it as a query string and prints
 * each key/value pair after URL‑decoding.
 * ---------------------------------------------------------------------- */
int main(void)
{
    static char line[LINE_MAX];
    static char key[KEY_MAX];
    static char val[VAL_MAX];

    /* Read a line from stdin */
    if (fgets(line, sizeof(line), stdin) == NULL) {
        puts("NO_INPUT");
        return 0;
    }

    /* Strip trailing newline / carriage‑return characters */
    size_t len = strlen(line);
    while (len > 0 && (line[len-1] == '\n' || line[len-1] == '\r')) {
        line[--len] = '\0';
    }

    size_t pos = 0;               /* current position in the line */

    while (pos < len) {
        /* ---- parse key ------------------------------------------------- */
        size_t key_start = pos;
        while (pos < len && line[pos] != '=' && line[pos] != '&')
            ++pos;
        size_t key_len = pos - key_start;
        url_decode(line + key_start, key_len, key);

        /* ---- parse value ----------------------------------------------- */
        if (pos < len && line[pos] == '=') {
            ++pos;                                 /* skip '=' */
            size_t val_start = pos;
            while (pos < len && line[pos] != '&')
                ++pos;
            size_t val_len = pos - val_start;
            url_decode(line + val_start, val_len, val);
        } else {
            /* No '=', treat as empty value */
            val[0] = '\0';
        }

        /* ---- output ---------------------------------------------------- */
        printf("%s=%s\n", key, val);

        /* Skip the '&' separator, if present */
        if (pos < len && line[pos] == '&')
            ++pos;
    }

    return 0;
}
